import React, { FunctionComponent } from 'react';
import InputStyleWrapper, { InputStyle } from '../inputStyleWrapper';
import LabeledInput from '../labeledInput';

type InputType = Omit<React.InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange'>;

export interface TimeInputProps {
  onChange: (time: string | undefined) => void;
  value: string;
  active?: boolean;
  label: string;
}

const TimeInput: FunctionComponent<TimeInputProps & InputType> = ({
  onChange,
  value,
  active,
  label,
  id,
  ...input
}) => (
  <InputStyleWrapper inputStyle={InputStyle.clean}>
    <LabeledInput
      id={id}
      htmlFor={id}
      label={label}
      type="time"
      active={active}
      onChange={(event) => onChange(event.target.value)}
      value={value}
      {...input}
      className="margin-left-10"
    />
  </InputStyleWrapper>
);

export default TimeInput;
