import React, { FunctionComponent } from 'react';
import { Field } from 'react-final-form';
import { TimeInput } from '../../../atoms';

export type TimeInputProps = {
  id?: string;
  label: string;
  name: string;
  className?: string;
  required?: boolean;
  changeListener?: (time?: string) => void;
};

const FormTimeInput: FunctionComponent<TimeInputProps> = ({
  id,
  label,
  name,
  className,
  changeListener,
}) => (
  <Field
    name={name}
    render={({ input }) => (
      <TimeInput
        id={id}
        label={label}
        className={className}
        active
        {...input}
        onChange={(value) => {
          input.onChange(value);
          changeListener?.(value);
        }}
      />
    )}
  />
);

export default FormTimeInput;
